INSERT INTO `articles` VALUES (1,5,'How to Answer Tell Me About Yourself','how-to-answer-tell-me-about-yourself','Preparation','A practical structure for a confident interview opening.','Start with your current role, connect your most relevant achievements, and close with why the target role fits your next step.',1,'2026-05-26 18:34:36','2026-05-25 16:52:02','2026-05-26 18:34:36',NULL),(2,5,'Fresher Interview Checklist','fresher-interview-checklist','Freshers','Simple preparation steps before your first interview.','Revise your projects, prepare a short introduction, practice common HR questions, and keep examples ready for teamwork, learning ability, and problem solving.',1,'2026-05-26 18:34:36','2026-05-25 16:52:02','2026-05-26 18:34:36',NULL),(3,5,'Salary Negotiation for Experienced Candidates','experienced-salary-negotiation','Experienced','How to discuss compensation with confidence.','Anchor your expected salary with market research, current responsibilities, measurable achievements, and the scope of the role you are interviewing for.',1,'2026-05-26 18:34:36','2026-05-25 16:52:02','2026-05-26 18:34:36',NULL),(4,5,'Final Round Preparation','final-round-preparation','Preparation','What to polish before the last conversation.','Review the job description, prepare business-impact examples, ask thoughtful questions, and be ready to explain why this company and role fit your next step.',1,'2026-05-26 18:34:36','2026-05-25 16:52:02','2026-05-26 18:34:36',NULL);
