INSERT INTO `cover_letters` VALUES (1,NULL,41,NULL,'uicx0S5TaKk5vwB31wZhYNAasZj8xNCkZi7A2HzZ','Web  Developer','Google','{\"id\": 1, \"body\": \"<p>Dear Hiring Team at Google,</p><p>I am excited to apply for Web  Developer at Google. I bring hands-on experience delivering reliable, user-focused work and collaborating across teams to ship high-quality outcomes.</p><p>My background aligns well with the role requirements, and I am confident I can contribute quickly.</p><p>I am especially interested in your focus on We are looking for a Senior Laravel Developer to join our team. You will be responsible for building scalable APIs, managing databases, and improving our SaaS product\'s performance., and I would value the opportunity to contribute with strong ownership, communication, and execution.</p><p>Sincerely,\\nGautam Sharma</p>\", \"name\": \"Gautam Sharma\", \"email\": \"gautamrajanexpert@gmail.com\", \"mobile\": \"+916205499691\", \"skills\": null, \"company\": \"Google\", \"job_role\": \"Web  Developer\", \"location\": null, \"templateId\": 41, \"template_id\": 41, \"company_name\": \"Google\", \"job_description\": \"We are looking for a Senior Laravel Developer to join our team. You will be responsible for building scalable APIs, managing databases, and improving our SaaS product\'s performance.\", \"resume_uploaded\": true}',0,'2026-05-25 20:21:23','2026-05-25 20:21:58'),(2,23,46,NULL,'VtAU06Og79vQWgrW6F6xzJfwtl2lYDENy8whEpkp','Senior Laravel Developer','Acme SaaS','{\"body\": \"Dear Hiring Team at Acme SaaS,\\n\\nI am excited to apply for Senior Laravel Developer at Acme SaaS. I bring hands-on experience delivering reliable, user-focused work and collaborating across teams to ship high-quality outcomes.\\n\\nMy background includes Laravel, PHP, MySQL, and I am confident these strengths align well with your requirements.\\n\\nI am especially interested in your focus on We are looking for a Senior Laravel Developer to join our team. You will be responsible for b